  "elevator6x2.hex": "@0\n00 00\n01 02\n15 02\n25 02\n28 06\n61 02\n75 02\n85 02\n38 06\n31 06\n24 06\nD5 07\nE4 07\n65 02\n04 02\n48 06\n01 00\n58 06\n01 03\n54 06\n8B 08\n41 06\n78 07\nAB 08\n01 02\n15 02\n25 02\n35 02\n28 06\n61 02\n75 02\n85 02\n95 02\n38 06\n31 06\n24 06\nD5 07\nE4 07\n75 02\n14 02\n48 06\n11 00\n25 00\n58 06\n11 03\n25 03\n54 06\n8B 08\n41 06\n88 07\nAB 08\n01 02\n15 02\n25 02\n35 02\n45 02\n28 06\n61 02\n75 02\n85 02\n95 02\nA5 02\n38 06\n31 06\n24 06\nD5 07\nE4 07\n85 02\n24 02\n48 06\n31 00\n45 00\n58 06\n31 03\n45 03\n54 06\n8B 08\n41 06\n98 07\nAB 08\n11 02\n25 02\n35 02\n45 02\n55 02\n28 06\n71 02\n85 02\n95 02\nA5 02\nB5 02\n38 06\n31 06\n24 06\nD5 07\nE4 07\n95 02\n34 02\n48 06\n51 00\n65 00\n58 06\n51 03\n65 03\n54 06\n8B 08\n41 06\nA8 07\nAB 08\n21 02\n35 02\n45 02\n55 02\n28 06\n81 02\n95 02\nA5 02\nB5 02\n38 06\n31 06\n24 06\nD5 07\nE4 07\nA5 02\n44 02\n48 06\n71 00\n85 00\n58 06\n71 03\n85 03\n54 06\n8B 08\n41 06\nB8 07\nAB 08\n31 02\n45 02\n55 02\n28 06\n91 02\nA5 02\nB5 02\n38 06\n31 06\n24 06\nD5 07\nE4 07\nB5 02\n54 02\n48 06\n91 00\n58 06\n91 03\n54 06\n8B 08\n41 06\nC8 07\nAB 08\n01 03\n05 00\n08 00\n11 03\n15 00\n18 00\n21 03\n25 00\n28 00\n31 03\n35 00\n38 00\n41 03\n45 00\n48 00\n51 03\n55 00\n58 00\n61 03\n65 00\n68 00\n71 03\n75 00\n78 00\n81 03\n85 00\n88 00\n91 03\n95 00\n98 00\nA1 03\nA5 00\nA8 00\nB1 03\nB5 00\nB8 00\nC1 03\nC5 00\nC8 00\nD1 03\nD5 00\nD8 00\nE1 03\nE5 00\nE8 00\nF1 03\nF5 00\nF8 00\n01 04\n05 01\n08 01\n11 04\n15 01\n18 01\n21 04\n25 01\n28 01\n31 04\n35 01\n38 01\n41 04\n45 01\n48 01\n51 04\n55 01\n58 01\nF1 05\n04 06\n18 06\nF1 05\n08 06\n01 02\n15 02\n25 02\n35 02\n45 02\n55 02\n82 08\n05 02\n08 02\n01 00\n74 07\nA5 00\n28 06\n11 00\n25 00\n84 07\nB5 00\n38 06\n31 00\n45 00\n94 07\nC5 00\n48 06\n51 00\n65 00\nA4 07\nD5 00\n58 06\n71 00\n85 00\nB4 07\nE5 00\n68 06\n91 00\nC4 07\nF5 00\n78 06\n71 06\n43 02\n98 06\n61 06\n75 06\n33 02\n95 06\n98 06\n51 06\n65 06\n75 06\n23 02\n95 06\n98 06\n41 06\n55 06\n65 06\n75 06\n13 02\n95 06\n98 06\n31 06\n45 06\n55 06\n65 06\n75 06\n03 02\n95 06\n98 06\n21 06\n13 02\nA8 06\n21 06\n35 06\n23 02\nA5 06\nA8 06\n21 06\n35 06\n45 06\n33 02\nA5 06\nA8 06\n21 06\n35 06\n45 06\n55 06\n43 02\nA5 06\nA8 06\n21 06\n35 06\n45 06\n55 06\n65 06\n53 02\nA5 06\nA8 06\n21 06\n03 02\nB8 06\n31 06\n13 02\nB5 06\nB8 06\n41 06\n23 02\nB5 06\nB8 06\n51 06\n33 02\nB5 06\nB8 06\n61 06\n43 02\nB5 06\nB8 06\n71 06\n53 02\nB5 06\nB8 06\n11 06\n33 07\nF8 06\n11 06\n23 07\n34 07\n08 07\n11 06\n24 07\nB3 06\nC8 06\n11 07\nA6 06\n93 06\n13 06\n24 07\nC4 06\nD8 06\nD2 06\nA3 06\n13 06\n24 07\nC4 06\nE8 06\nFB 06\n91 08\n38 07\n0B 07\n91 08\n28 07\n68 01\nAB 08\nC1 06\n03 02\n8B 08\n91 08\nA8 00\n08 00\nC1 06\n13 02\n8B 08\n91 08\nB8 00\n18 00\n28 00\nC1 06\n23 02\n8B 08\n91 08\nC8 00\n38 00\n48 00\nC1 06\n33 02\n8B 08\n91 08\nD8 00\n58 00\n68 00\nC1 06\n43 02\n8B 08\n91 08\nE8 00\n78 00\n88 00\nC1 06\n53 02\n8B 08\n91 08\nF8 00\n98 00\nCB 06\nA1 08\n28 07\n38 07\n68 01\nAB 08\nDB 06\n41 02\n58 02\n31 02\n48 02\n21 02\n38 02\n11 02\n28 02\n01 02\n18 02\n91 08\n08 02\nA1 08\n18 07\nEB 06\n11 02\n08 02\n21 02\n18 02\n31 02\n28 02\n41 02\n38 02\n51 02\n48 02\n91 08\n58 02\n18 07\nAB 08\n1B 06\nD1 06\n88 01\nE1 06\n98 01\nAB 08\n91 06\nA5 06\nB5 06\n25 07\nD8 07\n61 02\n75 02\n85 02\n95 02\nA5 02\nB5 02\n82 08\n65 02\n68 02\n01 00\n73 07\n05 01\n28 06\n11 00\n25 00\n83 07\n15 01\n38 06\n31 00\n45 00\n93 07\n25 01\n48 06\n51 00\n65 00\nA3 07\n35 01\n58 06\n71 00\n85 00\nB3 07\n45 01\n68 06\n91 00\nC3 07\n55 01\n78 06\n71 06\nA3 02\n98 06\n61 06\n75 06\n93 02\n95 06\n98 06\n51 06\n65 06\n75 06\n83 02\n95 06\n98 06\n41 06\n55 06\n65 06\n75 06\n73 02\n95 06\n98 06\n31 06\n45 06\n55 06\n65 06\n75 06\n63 02\n95 06\n98 06\n21 06\n73 02\nA8 06\n21 06\n35 06\n83 02\nA5 06\nA8 06\n21 06\n35 06\n45 06\n93 02\nA5 06\nA8 06\n21 06\n35 06\n45 06\n55 06\nA3 02\nA5 06\nA8 06\n21 06\n35 06\n45 06\n55 06\n65 06\nB3 02\nA5 06\nA8 06\n21 06\n63 02\nB8 06\n31 06\n73 02\nB5 06\nB8 06\n41 06\n83 02\nB5 06\nB8 06\n51 06\n93 02\nB5 06\nB8 06\n61 06\nA3 02\nB5 06\nB8 06\n71 06\nB3 02\nB5 06\nB8 06\n11 06\n63 07\nF8 06\n11 06\n53 07\n64 07\n08 07\n11 06\n54 07\nB3 06\nC8 06\n41 07\nA6 06\n93 06\n13 06\n54 07\nC4 06\nD8 06\nD2 06\nA3 06\n13 06\n54 07\nC4 06\nE8 06\nFB 06\n91 08\n68 07\n0B 07\n91 08\n58 07\n78 01\nAB 08\nC1 06\n63 02\n8B 08\n91 08\n08 01\n08 00\nC1 06\n73 02\n8B 08\n91 08\n18 01\n18 00\n28 00\nC1 06\n83 02\n8B 08\n91 08\n28 01\n38 00\n48 00\nC1 06\n93 02\n8B 08\n91 08\n38 01\n58 00\n68 00\nC1 06\nA3 02\n8B 08\n91 08\n48 01\n78 00\n88 00\nC1 06\nB3 02\n8B 08\n91 08\n58 01\n98 00\nCB 06\nA1 08\n58 07\n68 07\n78 01\nAB 08\nDB 06\nA1 02\nB8 02\n91 02\nA8 02\n81 02\n98 02\n71 02\n88 02\n61 02\n78 02\n91 08\n68 02\nA1 08\n48 07\nEB 06\n71 02\n68 02\n81 02\n78 02\n91 02\n88 02\nA1 02\n98 02\nB1 02\nA8 02\n91 08\nB8 02\n48 07\nAB 08\n1B 06\nD1 06\nA8 01\nE1 06\nB8 01\nAB 08\n91 06\nA5 06\nB5 06\n55 07\nE8 07\n0F 00\n",
  "ttlc_loopback.hex": "@0\n00 00\n01 03\n08 00\n11 03\n18 00\n21 03\n28 00\n31 03\n38 00\n41 03\n48 00\n51 03\n58 00\n61 03\n68 00\n71 03\n78 00\n81 03\n88 00\n91 03\n98 00\nA1 03\nA8 00\nB1 03\nB8 00\nC1 03\nC8 00\nD1 03\nD8 00\nE1 03\nE8 00\nF1 03\nF8 00\n01 04\n08 01\n11 04\n18 01\n21 04\n28 01\n31 04\n38 01\n41 04\n48 01\n51 04\n58 01\n61 04\n68 01\n71 04\n78 01\n81 04\n88 01\n91 04\n98 01\nA1 04\nA8 01\nB1 04\nB8 01\nC1 04\nC8 01\nD1 04\nD8 01\nE1 04\nE8 01\nF1 04\nF8 01\n01 05\n08 02\n11 05\n18 02\n21 05\n28 02\n31 05\n38 02\n41 05\n48 02\n51 05\n58 02\n61 05\n68 02\n71 05\n78 02\n81 05\n88 02\n91 05\n98 02\nA1 05\nA8 02\nB1 05\nB8 02\nC1 05\nC8 02\nD1 05\nD8 02\nE1 05\nE8 02\nF1 05\nF8 02\n0F 00\n"
